using Mist.Application.Contracts;
using Mist.Application.OptionalLocalWorks;
using Mist.Application.Storage;
using Mist.Core.Combat;
using Mist.Core.Contracts;
using Mist.Core.OptionalLocalWorks;
using Mist.DebugCandidates;
using Mist.Infrastructure.Storage;
using Mist.Tests.ChapterSix;
using static Mist.Tests.Storage.StorageCases;
using static Mist.Tests.TestRegistry;

namespace Mist.Tests.OptionalLocalWorks;

public static class FieldRelayRepairCases
{
    private static readonly Mist.Core.Content.RuntimeCatalog Catalog=Q102.Q102Cases.Catalog();
    public static FieldRelayContract Contract()=>FieldRelayContract.ParseJson(File.ReadAllText(Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../..","content/source/optional_local_works/field_relay_contract.json"))));
    private static ProfileStore Store(string label)=>new(Path.Combine(Environment.GetEnvironmentVariable("MISTSEA_TEST_OUTPUT")??Path.GetTempPath(),"field-relay-normal-"+label+"-"+Guid.NewGuid()),Catalog.ReleaseId);
    private static void Success(CommandResult r)=>Require(r.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,StrictJson.Serialize(r));
    public static string MainWorld(BranchSnapshot s)=>StrictJson.Serialize(new{entities=s.Entities.Where(e=>e.Id!="actor"&&!e.Id.StartsWith(FieldRelayRepairService.StateId,StringComparison.Ordinal)&&e.Id!=FieldRelayRepairService.CombatId&&e.Id!="R6:result:"+FieldRelayRepairService.Encounter&&e.Id!="material:"+FieldRelayRepairService.MaterialId).OrderBy(e=>e.Id),items=s.Items.Where(i=>i.Id!="R6-AUX-RELAY-01"&&i.Id!="R6-AUX-BRAKE-PIN-01").OrderBy(i=>i.Id),balances=s.Balances.OrderBy(x=>x.Key)});
    private sealed class Run
    {
        public ProfileStore Store {get;}public ChapterSixCases.Run Chapter {get;}public FieldRelayRepairService Service {get;}
        public FieldRelayState State=>Done(Service.ViewAsync()).State!;
        public Run(ProfileStore s,bool ready=true){Store=s;var p=ChapterSixCases.ActualArrival(s);Chapter=new(s,p.Service,p.Interior);Service=new(s,Catalog,Contract(),p.Service);if(ready){Chapter.Node601();Chapter.RidgeReady();Chapter.Base("R6");Chapter.Node603();Chapter.At("R6-S06.repair");}}
        public void Accept(){Success(Done(Service.DiscoverContractAsync()));Success(Done(Service.DecideScopeAsync("accept")));}
        public void Isolate(){Success(Done(Service.SetAuxSwitchAsync("OFF")));Success(Done(Service.FitDedicatedPinAsync(Contract().PinSerial)));Success(Done(Service.VerifyZeroAsync("AUX",0,State.Configuration)));}
        public void Repair(){Success(Done(Service.RefitSameRelayAsync(Contract().RelaySerial)));Success(Done(Service.VerifyZeroAsync("AUX",0,State.Configuration)));Success(Done(Service.TestReturnAsync(State.Configuration)));Success(Done(Service.CompleteAsync()));}
    }
    public static void Register()
    {
        Add("CP-FIELD-RELAY-05","Actual zero-XP predecessors and protected Q603 closure export a native auxiliary work entry without local permission, devices or optional results",()=>
        {using var s=Store("native-entry");var r=new Run(s);var snap=Done(s.SnapshotAsync());Require(snap.Balances["experience"]==13700&&r.Chapter.View.Actor.Scene=="R6-S06"&&r.Chapter.View.Actor.Position==new Mist.Core.Exploration.Point2(74,65)&&Done(r.Service.ViewAsync()).State is null&&!snap.Items.Any(i=>i.Id.StartsWith("R6-AUX-",StringComparison.Ordinal))&&snap.Receipts.All(x=>!x.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)&&!x.SemanticKey.StartsWith("internal:",StringComparison.Ordinal)));Done(s.CreateCheckpointAsync("manual"));File.WriteAllText(Path.Combine(s.RootPath,"normal-field-relay-native-entry.json"),StrictJson.Serialize(new{scope="actual normal zero-XP preceding chapters, Q601 and protected Q603 already closed; no auxiliary contract acquisition or device work",profile_root=s.RootPath,experience=13700,actor=r.Chapter.View.Actor,receipts=snap.Receipts,human_native_play="not_run",language_calibration="human_pending",audio="no auxiliary recording"}));});
        Add("CP-FIELD-RELAY-03","A current same-device OFF, dedicated pin and AUX zero method controls the optional relay without attacking, then requires refit and a new current return check",()=>
        {using var s=Store("method");var r=new Run(s);string main=MainWorld(Done(s.SnapshotAsync()));r.Accept();Throws<InvalidOperationException>(()=>Done(r.Service.VerifyZeroAsync("AUX",0,r.State.Configuration)));Success(Done(r.Service.SetAuxSwitchAsync("OFF")));Throws<InvalidOperationException>(()=>Done(r.Service.FitDedicatedPinAsync("R6-finite:BASE-TWR-R6-base_isolator:1")));Success(Done(r.Service.FitDedicatedPinAsync(Contract().PinSerial)));Throws<InvalidOperationException>(()=>Done(r.Service.VerifyZeroAsync("REF",10,r.State.Configuration)));Success(Done(r.Service.VerifyZeroAsync("AUX",0,r.State.Configuration)));Require(r.State.ThreatControlled&&!r.State.Repaired&&Done(r.Service.EncounterAsync()) is null);Success(Done(r.Service.RefitSameRelayAsync(Contract().RelaySerial)));Throws<InvalidOperationException>(()=>Done(r.Service.TestReturnAsync(r.State.Configuration)));Success(Done(r.Service.VerifyZeroAsync("AUX",0,r.State.Configuration)));Success(Done(r.Service.TestReturnAsync(r.State.Configuration)));Success(Done(r.Service.TestReturnAsync(r.State.Configuration)));Success(Done(r.Service.CompleteAsync()));Require(Done(r.Service.CompleteAsync()).Status==CommitStatus.AlreadyCommitted&&r.State.Completed&&MainWorld(Done(s.SnapshotAsync()))==main&&Done(s.SnapshotAsync()).Receipts.Count(x=>x.SemanticKey=="R6:ENC-R6-06:result")==1&&Done(s.SnapshotAsync()).Receipts.Count(x=>x.SemanticKey==FieldRelayRepairService.Completion)==1&&Done(s.SnapshotAsync()).Items.Count(i=>i.Id==Contract().RelaySerial)==1);});
        Add("CP-FIELD-RELAY-03","Real BattleEngine threat control grants no isolation, pin, tower or delivery; withdrawal and cancelled or continued previews preserve the same finite work instance",()=>
        {using var s=Store("combat");var r=new Run(s);string main=MainWorld(Done(s.SnapshotAsync()));r.Accept();var instance=r.State.Instance;Success(Done(r.Service.BeginEncounterAsync()));var first=Done(r.Service.EncounterAsync())!;var request=BattleCandidate.Choose(new(r.Service.BattleDefinitions,first.Battle));var cancelled=Done(r.Service.PreviewActionAsync(request));Require(cancelled.Action.Legal);long seq=s.Session.Sequence;r.Service.ClosePreview(cancelled.Token);Require(Done(r.Service.ConfirmPreviewAsync(cancelled.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq);var stale=Done(r.Service.PreviewActionAsync(request));Done(s.ContinueAsync());Require(Done(r.Service.ConfirmPreviewAsync(stale.Token)).Status==CommitStatus.Rejected);Success(Done(r.Service.WithdrawEncounterAsync()));Require(r.State.Instance==instance&&!r.State.ThreatControlled&&Done(r.Service.EncounterAsync())!.Battle.Outcome==CombatOutcome.Withdrawn);Success(Done(r.Service.BeginEncounterAsync()));for(int i=0;i<900&&Done(r.Service.EncounterAsync())!.Battle.Outcome==CombatOutcome.Active;i++){var b=Done(r.Service.EncounterAsync())!.Battle;var p=Done(r.Service.PreviewActionAsync(BattleCandidate.Choose(new(r.Service.BattleDefinitions,b))));Require(p.Action.Legal,p.Description);Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));}Require(Done(r.Service.EncounterAsync())!.Battle.Outcome==CombatOutcome.Controlled&&r.State.ThreatControlled&&r.State.AuxSwitch=="LIVE"&&r.State.ZeroCheck is null&&!r.State.Repaired);Throws<InvalidOperationException>(()=>Done(r.Service.RefitSameRelayAsync(Contract().RelaySerial)));r.Isolate();r.Repair();Require(MainWorld(Done(s.SnapshotAsync()))==main&&Done(s.SnapshotAsync()).Receipts.Count(x=>x.SemanticKey=="R6:ENC-R6-06:result")==1&&Done(s.SnapshotAsync()).Balances["experience"]==13700);});
        Add("CP-FIELD-RELAY-03","Untouched arrival, incorrect stand and a different local relay custody cannot produce scoped work or borrow protected cargo",()=>
        {using var s=Store("guards");var r=new Run(s,false);long seq=s.Session.Sequence;Throws<InvalidOperationException>(()=>Done(r.Service.DiscoverContractAsync()));Require(s.Session.Sequence==seq);r.Chapter.Node601();r.Chapter.RidgeReady();r.Chapter.Base("R6");r.Chapter.Node603();r.Chapter.At("R6-S05.supplement");Throws<InvalidOperationException>(()=>Done(r.Service.DiscoverContractAsync()));r.Chapter.At("R6-S06.repair");Success(Done(r.Service.DiscoverContractAsync()));Success(Done(r.Service.DecideScopeAsync("decline")));Require(!Done(s.SnapshotAsync()).Items.Any(i=>i.Id.StartsWith("R6-AUX-",StringComparison.Ordinal)));Success(Done(r.Service.DecideScopeAsync("accept")));var item=Done(s.SnapshotAsync()).Items.Single(i=>i.Id==Contract().RelaySerial);Mist.Tests.NPC.NpcCases.Fixture(s,"negative:relay-custody","negative_custody_probe",new{not_positive_setup=true},items:[new(item.Id,item.DefinitionId,item.OwnerKind,item.OwnerId,"warehouse","negative-other-local-owner",null)]);seq=s.Session.Sequence;Throws<InvalidOperationException>(()=>Done(r.Service.SetAuxSwitchAsync("OFF")));Require(s.Session.Sequence==seq&&!r.State.Completed&&Done(s.SnapshotAsync()).Items.Where(i=>i.Id.StartsWith("R6-supplement:",StringComparison.Ordinal)).All(i=>i.OwnerKind=="warehouse"));});
    }
}
